import {createRecoveryDemo} from '../shared/recovery-demo.js?v=5.12.0';
import {recoveryCopy} from '../shared/recovery-demo-copy.js?v=5.12.0';
import {ownerAuthCopy} from '../shared/owner-auth-copy.js?v=5.11.0';
import {brandLogo,brandMark} from '../shared/brand.js?v=5.6.0';
import {esc,icon,languageOptions,getLang,setLang,money} from '../shared/core.js?v=5.6.0';
import {formatBooking,partyLabel,tableLabel} from '../shared/locale.js?v=5.6.0';
import {SAMPLE_COPY} from '../shared/owner-sample.js?v=5.6.0';
import {ORDER_COPY} from '../shared/order-copy.js?v=5.6.0';
const root=document.querySelector('#recovery-app');let lang=getLang(),error='';
const demo=createRecoveryDemo(localStorage),counts=()=>{const s=demo.snapshot();return {menu:s.items.length,orders:s.orders.length,bookings:s.reservations.length};};
const mailIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="3"/><path d="m4 7 8 6 8-6"/></svg>';
const primary=(action,label)=>`<button class="button primary recovery-primary" type="button" data-do="${action}">${esc(label)}${icon('arrow')}</button>`;
function metrics(){const c=recoveryCopy(lang);return `<div class="recovery-metrics">${Object.entries(counts()).map(([key,value])=>`<div><strong>${value}</strong><span>${esc(c[key])}</span></div>`).join('')}</div>`;}
function passwordField(name){const a=ownerAuthCopy(lang);return `<label for="demo-${name}">${esc(a[name])}</label><div class="auth-password"><input id="demo-${name}" type="password" name="${name}" autocomplete="off" minlength="12" maxlength="128" required aria-describedby="demo-password-note"><button type="button" data-show="demo-${name}" aria-controls="demo-${name}" aria-pressed="false">${esc(a.show)}</button></div>`;}
function records(){const c=recoveryCopy(lang),s=demo.snapshot(),o=ORDER_COPY[lang];
 const tabs=`<div class="recovery-tabs" role="tablist" aria-label="${esc(c.shopTitle)}">${['orders','bookings','menu','shop'].map(key=>`<button type="button" role="tab" id="tab-${key}" aria-controls="recovery-records" aria-selected="${demo.tab===key}" tabindex="${demo.tab===key?0:-1}" data-tab="${key}">${esc(c[key])}</button>`).join('')}</div>`;
 let body='';if(demo.tab==='orders')body=s.orders.map(order=>`<article class="recovery-record"><header><strong>#${order.number}</strong><span>${esc(order.fulfillment.channel==='online'?o.onlineOrder:tableLabel(order.table,lang))}</span></header><p>${esc(order.lines.map(line=>line.name[lang]+' × '+line.quantity).join(' · '))}</p><b>${money(order.total,lang)}</b>${order.fulfillment.channel==='online'?`<small>${esc(order.fulfillment.address)}<br>${esc(order.fulfillment.phone)}</small>`:''}</article>`).join('');
 if(demo.tab==='bookings')body=s.reservations.map(r=>`<article class="recovery-record"><header><strong>${esc(r.name)}</strong><span>${esc(tableLabel(r.table,lang))}</span></header><p>${esc(formatBooking(r.date,r.time,lang))}</p><b>${esc(partyLabel(r.partySize,lang))}</b></article>`).join('');
 if(demo.tab==='menu')body=s.items.map(m=>`<article class="recovery-record"><header><strong>${esc(m.name[lang])}</strong><b>${money(m.price,lang)}</b></header></article>`).join('');
 if(demo.tab==='shop')body=`<article class="recovery-record"><h2>${esc(s.store.name)}</h2><p>${esc(SAMPLE_COPY[lang].sampleAddress)}</p><p>${esc(SAMPLE_COPY[lang].sampleAbout)}</p><b>${esc(SAMPLE_COPY[lang].sampleHours)} · ${esc(s.store.hours)}</b></article>`;
 return tabs+`<section id="recovery-records" role="tabpanel" aria-labelledby="tab-${demo.tab}" tabindex="0">${body}</section>`;
}
function render(focus=false){const c=recoveryCopy(lang),a=ownerAuthCopy(lang),index={email:0,inbox:1,password:2,done:3,shop:3}[demo.stage];document.documentElement.lang=lang;document.title=c.badge+' · one shop ai';
 let content='';
 if(demo.stage==='email')content=`${brandMark('greeting',true)}<h1 tabindex="-1">${esc(c.title)}</h1><p>${esc(c.intro)}</p><form data-form="email" class="auth-form"><label for="demo-email">${esc(c.email)}</label><input id="demo-email" name="email" type="email" required maxlength="254" autocomplete="off" value="${esc(demo.email)}"><p class="recovery-feedback" role="alert">${esc(error)}</p><button class="button primary recovery-primary">${esc(c.send)}${icon('arrow')}</button></form>`;
 if(demo.stage==='inbox')content=`<div class="recovery-mail-icon">${mailIcon}</div><h1 tabindex="-1">${esc(c.inboxTitle)}</h1><p>${esc(c.inboxNote)}</p><article class="recovery-email"><header><span>one shop ai · Rami</span><small>${esc(c.to)} · ${esc(demo.email)}</small></header><h2>${esc(c.subject)}</h2><p>${esc(c.mailBody)}</p>${primary('open',c.open)}<small>${esc(c.expiry)}</small></article><p class="recovery-feedback" role="alert">${esc(error)}</p>`;
 if(demo.stage==='password')content=`${brandMark('thinking',true)}<h1 tabindex="-1">${esc(c.passwordTitle)}</h1><p>${esc(c.passwordNote)}</p><form class="auth-form" data-form="password">${passwordField('password')}${passwordField('confirm')}<p id="demo-password-note" class="auth-hint">${esc(a.passwordHint)}<br>${esc(c.demoPassword)}</p><p class="recovery-feedback" role="alert">${esc(error)}</p><button class="button primary recovery-primary">${esc(c.save)}${icon('check')}</button></form>`;
 if(demo.stage==='done')content=`${brandMark('greeting',true)}<span class="recovery-complete">${icon('check')} ${esc(c.doneStep)}</span><h1 tabindex="-1">${esc(c.doneTitle)}</h1><p>${esc(c.doneNote)}</p>${metrics()}${primary('shop',c.returnShop)}`;
 if(demo.stage==='shop')content=`<div class="recovery-shop-title">${brandMark('order',true)}<div><span>주모 · JUMO</span><h1 tabindex="-1">${esc(c.shopTitle)}</h1></div></div><p class="recovery-preserved">${icon('check')}${esc(c.preserved)}</p>${metrics()}${records()}`;
 root.innerHTML=`<div class="recovery-shell"><header class="recovery-header"><a class="platform-brand" href="../?lang=${lang}&v=5.12.0">${brandLogo()}</a><label class="language-select">${icon('globe')}<select aria-label="Language" id="recovery-language">${languageOptions(lang)}</select></label></header><div class="recovery-boundary">${icon('spark')}<div><b>${esc(c.badge)}</b><span>${esc(c.boundary)}</span></div></div><div class="recovery-layout"><aside class="recovery-progress"><span>one shop ai · Rami</span><ol>${['emailStep','inboxStep','passwordStep','doneStep'].map((k,i)=>`<li class="${i===index?'current':i<index?'complete':''}" ${i===index?'aria-current="step"':''}><span>${i<index?icon('check'):'0'+(i+1)}</span><b>${esc(c[k])}</b></li>`).join('')}</ol><div class="recovery-shop-note"><strong>주모 · JUMO</strong><p>${esc(c.passwordNote)}</p></div></aside><main class="recovery-panel ${demo.stage==='shop'?'recovery-dashboard':''}">${content}${demo.stage!=='email'?`<button class="auth-text-button" data-do="restart">${esc(c.restart)}</button>`:''}</main></div><footer class="recovery-footer"><a href="owner.html?lang=${lang}&v=5.12.0">${icon('arrow')}${esc(c.back)}</a><span>원샵 · one shop ai</span></footer></div>`;
 if(focus){root.querySelector('h1')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
}
function action(fn){try{fn();error='';render(true);}catch(e){error=recoveryCopy(lang)[e.message]||ownerAuthCopy(lang)[e.message]||ownerAuthCopy(lang).cloudError;const alert=root.querySelector('[role="alert"]');if(alert)alert.textContent=error;}}
root.addEventListener('submit',e=>{e.preventDefault();const form=e.target,values=Object.fromEntries(new FormData(form));if(form.dataset.form==='email')action(()=>demo.request(values.email));if(form.dataset.form==='password'){action(()=>demo.reset(values.password,values.confirm));form.reset();}});
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.show){const input=document.getElementById(b.dataset.show),show=input.type==='password';input.type=show?'text':'password';b.textContent=ownerAuthCopy(lang)[show?'hide':'show'];b.setAttribute('aria-pressed',String(show));return;}if(b.dataset.tab){demo.tab=b.dataset.tab;render();root.querySelector('#tab-'+demo.tab)?.focus();return;}if(b.dataset.do==='open')action(()=>demo.open());if(b.dataset.do==='shop')action(()=>demo.returnShop());if(b.dataset.do==='restart')action(()=>demo.restart());});
root.addEventListener('keydown',e=>{if(!e.target.matches('[role="tab"]')||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const keys=['orders','bookings','menu','shop'];let i=keys.indexOf(demo.tab);i=e.key==='Home'?0:e.key==='End'?3:(i+(e.key==='ArrowRight'?1:3))%4;demo.tab=keys[i];render();root.querySelector('#tab-'+demo.tab)?.focus();});
root.addEventListener('change',e=>{if(e.target.id==='recovery-language'){lang=e.target.value;setLang(lang);error='';render();}});
render();
